use xiom.io;

use xiom.string;
use xiom.convert;
type Scheduler = {
  slots: Map[Int, Str];
}

fn Scheduler.new() -> Scheduler {
  return Scheduler{ slots: Map[Int, Str].new() };
}

fn Scheduler.book(s: &mut Scheduler, time: Int, event: Str) -> Bool {
  if s.slots.contains(&time) {
    return false;
  }
  s.slots.insert(time, event);
  return true;
}

fn Scheduler.is_busy(s: &Scheduler, time: Int) -> Bool {
  return s.slots.contains(&time);
}

fn main() -> Int {
  var s: Scheduler = Scheduler.new();
  io.println(convert.bool_to_string(s.book(&mut s, 14, "Meeting")));
  io.println(convert.bool_to_string(s.book(&mut s, 12, "Lunch")));
  io.println(convert.bool_to_string(s.book(&mut s, 14, "Interview")));
  io.println(convert.bool_to_string(s.is_busy(&s, 14)));
  return 0;
}
